def fmt_entier(valeur):
    """Entier avec espace comme séparateur de milliers : 61 343 289."""
    return f"{valeur:,.0f}".replace(",", " ")


def fmt_decimal(valeur, decimales=2):
    """Décimal à la française : 3,95."""
    return f"{valeur:.{decimales}f}".replace(".", ",")


# =========================================================
# PREPARATION DE LA SERIE TEMPORELLE (notebook, sections V et VI.1)
# =========================================================
def preparer_serie(donnees):
    """Transforme la table des ventes importée en série mensuelle `ca_mensuel`.

    Retourne (serie, infos). `serie` vaut None si aucune ligne n'est exploitable.
    """
    ventes = donnees.copy()
    infos = {"lignes_sans_date": 0, "remise_convertie": False, "ecart_ca": None}

    # Étape 1 (notebook V) : supprimer les ventes sans date, car elles ne peuvent
    # pas être placées sur une série temporelle
    nb_avant = len(ventes)
    ventes["date_vente"] = pd.to_datetime(ventes["date_vente"], errors="coerce")
    ventes = ventes.dropna(subset=["date_vente"]).copy()
    infos["lignes_sans_date"] = nb_avant - len(ventes)
    if ventes.empty:
        return None, infos

    # Étape 2 : conversion des colonnes de calcul en nombres
    for colonne in ["quantite", "prix_unitaire_fcfa", "remise_pct"]:
        ventes[colonne] = pd.to_numeric(ventes[colonne], errors="coerce")
    ventes["remise_pct"] = ventes["remise_pct"].fillna(0)  # pas de remise renseignée = 0

    # Étape 3 : sécurité sur l'échelle de la remise. Elle doit être une fraction
    # (0,10 = 10 %) ; si des valeurs dépassent 1, elle est en pourcentage (10 = 10 %)
    if ventes["remise_pct"].max() > 1:
        ventes["remise_pct"] = ventes["remise_pct"] / 100
        infos["remise_convertie"] = True

    # Étape 4 : calcul du chiffre d'affaires net de chaque ligne de vente
    # (sums() ignore les valeurs manquantes, comme dans le notebook)
    ventes["chiffre_affaire_net_calcule"] = (
        ventes["quantite"] * ventes["prix_unitaire_fcfa"] * (1 - ventes["remise_pct"])
    )

    # Étape 5 : agrégation par mois (notebook VI.1) -> une ligne par mois
    ventes["mois"] = ventes["date_vente"].dt.to_period("M")
    serie = (
        ventes.groupby("mois", as_index=False)
        .agg(ca_mensuel=("chiffre_affaire_net_calcule", "sum"))
        .sort_values("mois")
    )

    # Étape 6 : contrôle de cohérence avec la colonne chiffre_affaire_net, si le fichier
    # la contient (c'est elle qui a servi à entraîner les modèles dans le notebook)
    if "chiffre_affaire_net" in ventes.columns:
        ca_fichier = pd.to_numeric(ventes["chiffre_affaire_net"], errors="coerce")
        mensuel_fichier = ca_fichier.groupby(ventes["mois"]).sum()
        mensuel_calcule = serie.set_index("mois")["ca_mensuel"]
        ecart = ((mensuel_calcule - mensuel_fichier).abs() / mensuel_fichier.abs()).replace(
            [np.inf, -np.inf], np.nan
        )
        infos["ecart_ca"] = float(ecart.max()) if ecart.notna().any() else None

    # Étape 7 : série continue. Un mois sans vente reçoit un chiffre d'affaires nul,
    # car les modèles saisonniers exigent des mois consécutifs
    periode_complete = pd.period_range(
        start=serie["mois"].min(), end=serie["mois"].max(), freq="M"
    )
    serie = (
        serie.set_index("mois")
        .reindex(periode_complete, fill_value=0)
        .rename_axis("mois")
        .reset_index()
    )

    # Étape 8 : date du premier jour de chaque mois (axe du temps des modèles et graphiques)
    serie["date_mois"] = serie["mois"].dt.to_timestamp()
    return serie, infos


# =========================================================
# OUTILS DE MODELISATION
# =========================================================
def _variables_mois(numeros_mois, colonnes_reference=None):
    """Variables 0/1 « mois » de la régression (janvier = mois de référence).

    - Sans `colonnes_reference` (entraînement) : colonnes m_2 ... m_12.
    - Avec `colonnes_reference` et DUMMIES_COMME_NOTEBOOK : reproduction exacte du notebook
      (variables construites sur les seuls mois fournis, premier mois supprimé,
      puis alignement sur les colonnes de l'entraînement).
    - Sinon : variables complètes, chaque mois a sa colonne.
    """
    if colonnes_reference is not None and DUMMIES_COMME_NOTEBOOK:
        brut = pd.get_dummies(pd.Series(numeros_mois), prefix="m", drop_first=True, dtype=float)
        return brut.reindex(columns=colonnes_reference, fill_value=0.0)
    categories = pd.Categorical(numeros_mois, categories=list(range(1, 13)))
    return pd.get_dummies(categories, prefix="m", drop_first=True, dtype=float)


def _dates_futures(derniere_date, n):
    """Les n premiers jours de mois qui suivent la dernière date de l'historique."""
    return pd.date_range(
        start=derniere_date + pd.offsets.MonthBegin(1), periods=n, freq="MS"
    )


def prevoir(code, df, n):
    """Entraîne le modèle `code` sur df (colonnes date_mois, ca_mensuel) et prévoit n mois.

    Chaque branche reprend les paramètres du notebook (section VII.2).
    """
    y = df["ca_mensuel"].astype(float).reset_index(drop=True)

    # a. Moyenne mobile : moyenne des 3 derniers mois connus, répétée sur l'horizon
    if code == "moyenne_mobile":
        prevision = np.repeat(y.iloc[-3:].mean(), n)

    # b. Lissage exponentiel de Holt-Winters : tendance amortie + saisonnalité annuelle additive
    elif code == "holt_winters":
        from statsmodels.tsa.holtwinters import ExponentialSmoothing
        modele = ExponentialSmoothing(
            y, trend="add", damped_trend=True, seasonal="add", seasonal_periods=12
        ).fit(optimized=True)
        prevision = modele.forecast(n).values

    # c. Régression linéaire : numéro du mois (t) + variables « mois » (saisonnalité)
    elif code == "regression":
        from sklearn.linear_model import LinearRegression
        # Variables explicatives de l'entraînement
        t_train = pd.DataFrame({"t": np.arange(len(df), dtype=float)})
        mois_train = _variables_mois(df["date_mois"].dt.month.values)
        X_train = pd.concat([t_train, mois_train], axis=1)
        # Variables explicatives de la période à prévoir (t continue après l'entraînement)
        dates_f = _dates_futures(df["date_mois"].iloc[-1], n)
        t_futur = pd.DataFrame({"t": np.arange(len(df), len(df) + n, dtype=float)})
        mois_futur = _variables_mois(dates_f.month.values, colonnes_reference=list(mois_train.columns))
        X_futur = pd.concat([t_futur, mois_futur], axis=1)[X_train.columns]
        # Ajustement puis prévision
        modele = LinearRegression().fit(X_train, y)
        prevision = modele.predict(X_futur)

    # d. Modèle autorégressif intégré à moyenne mobile saisonnier (1,1,1)(1,0,0,12)
    elif code == "autoregressif":
        from statsmodels.tsa.statespace.sarimax import SARIMAX
        modele = SARIMAX(
            y,
            order=(1, 1, 1),
            seasonal_order=(1, 0, 0, 12),
            enforce_stationarity=False,
            enforce_invertibility=False,
        ).fit(disp=False)
        prevision = modele.forecast(n).values

    # e. Prophet : tendance + saisonnalité annuelle (format attendu : colonnes ds et y)
    elif code == "prophet":
        from prophet import Prophet
        d = df[["date_mois", "ca_mensuel"]].rename(
            columns={"date_mois": "ds", "ca_mensuel": "y"}
        )
        modele = Prophet(
            yearly_seasonality=True, weekly_seasonality=False, daily_seasonality=False
        )
        modele.fit(d)
        futur = modele.make_future_dataframe(periods=n, freq="MS")
        prevision = modele.predict(futur).iloc[-n:]["yhat"].values

    else:
        raise ValueError(f"Modèle inconnu : {code}")

    return np.asarray(prevision, dtype=float)


def calculer_metriques(y_reel, y_prevu):
    """Les 3 métriques du notebook (fonction evaluer_modele)."""
    y_reel = np.asarray(y_reel, dtype=float)
    y_prevu = np.asarray(y_prevu, dtype=float)
    ecart = y_reel - y_prevu
    masque = y_reel != 0  # une division par zéro est impossible pour l'erreur en pourcentage
    erreur_pct = (
        np.mean(np.abs(ecart[masque] / y_reel[masque])) * 100 if masque.any() else np.nan
    )
    return {
        "erreur_absolue_moyenne": float(np.mean(np.abs(ecart))),            # MAE du notebook
        "racine_erreur_quadratique": float(np.sqrt(np.mean(ecart ** 2))),    # RMSE du notebook
        "erreur_pct_moyenne": float(erreur_pct),                             # MAPE du notebook
    }


def entrainer_et_prevoir(serie):
    """Reproduit le notebook : découpage, test des 5 modèles, choix du meilleur,
    réentraînement sur tout l'historique et prévision."""
    # Étape 1 (notebook VII.1) : série triée chronologiquement
    df = serie.sort_values("date_mois").reset_index(drop=True)

    # Étape 2 : découpage chronologique, 6 derniers mois pour le test
    train, test = df.iloc[:-MOIS_TEST], df.iloc[-MOIS_TEST:]

    # Étape 3 (notebook VII.2) : entraînement sur `train`, évaluation sur `test`
    lignes, predictions_test, avertissements = [], {}, []
    for code, nom in NOMS_MODELES.items():
        try:
            prevision = prevoir(code, train, MOIS_TEST)
            metriques = calculer_metriques(test["ca_mensuel"].values, prevision)
            if np.isnan(metriques["erreur_pct_moyenne"]):
                raise ValueError("erreur en pourcentage incalculable")
            lignes.append({"code": code, "modele": nom, **metriques})
            predictions_test[code] = prevision
        except Exception as erreur:
            # Un modèle qui échoue est écarté, les autres continuent
            avertissements.append(f"{nom} ignoré : {erreur}")

    if not lignes:
        raise RuntimeError("Aucun des 5 modèles n'a pu être entraîné sur ces données.")

    # Étape 4 : classement, le meilleur modèle a l'erreur moyenne en pourcentage la plus basse
    metriques_df = pd.DataFrame(lignes).sort_values("erreur_pct_moyenne").reset_index(drop=True)

    # Étape 5 (notebook VII.3) : réentraînement du meilleur modèle sur tout l'historique
    gagnant, prevision_future = None, None
    for code in metriques_df["code"]:
        try:
            prevision_future = prevoir(code, df, HORIZON_MAX)
            gagnant = code
            break
        except Exception as erreur:
            avertissements.append(f"{NOMS_MODELES[code]} : réentraînement impossible ({erreur})")
    if gagnant is None:
        raise RuntimeError("Impossible de produire une prévision finale.")

    # Un chiffre d'affaires ne peut pas être négatif : appliqué aux seules prévisions futures
    prevision_future = np.maximum(prevision_future, 0)

    # Étape 6 : table des mois futurs et de leur chiffre d'affaires prévu
    dates_f = _dates_futures(df["date_mois"].iloc[-1], HORIZON_MAX)
    prevision_df = pd.DataFrame({"date_mois": dates_f, "ca_prevu": prevision_future})

    # Étape 7 : variation de croissance, dernier mois historique -> premier mois prévu
    taux = None
    dernier_reel = float(df["ca_mensuel"].iloc[-1])
    if dernier_reel > 0:
        taux = (float(prevision_future[0]) - dernier_reel) / dernier_reel * 100

    return {
        "serie": df,
        "dates_test": test["date_mois"].values,
        "metriques": metriques_df,
        "pred_test": predictions_test[gagnant],
        "gagnant": gagnant,
        "prevision": prevision_df,
        "taux_croissance": taux,
        "avertissements": avertissements,
    }


# =========================================================
# TABLEAU, EXPORT ET GRAPHIQUES
# =========================================================
def tableau_previsions(res, n):
    """Tableau mensuel : valeur prévue et variations (mois précédent, même mois un an avant)."""
    serie = res["serie"]
    # Dictionnaire mois -> chiffre d'affaires (historique d'abord, puis prévisions ajoutées)
    valeurs = {p: v for p, v in zip(serie["mois"], serie["ca_mensuel"])}
    lignes = []
    for date, prevu in zip(res["prevision"]["date_mois"][:n], res["prevision"]["ca_prevu"][:n]):
        periode = pd.Period(date, freq="M")
        precedent = valeurs.get(periode - 1)      # mois précédent
        annee_prec = valeurs.get(periode - 12)    # même mois un an avant

        def variation(reference):
            if reference is None or reference <= 0:
                return np.nan
            return (prevu - reference) / reference * 100

        lignes.append({
            "Mois": periode.strftime("%Y-%m"),
            "Chiffre d'affaires prévu (francs CFA)": round(float(prevu)),
            "Variation par rapport au mois précédent (%)": variation(precedent),
            "Variation par rapport au même mois de l'année précédente (%)": variation(annee_prec),
        })
        valeurs[periode] = float(prevu)  # sert de « mois précédent » au mois suivant
    return pd.DataFrame(lignes)


def construire_excel(res, n):
    """Un seul fichier Excel : prévisions mensuelles + comparaison des 5 modèles."""
    # Feuille 1 : prévisions de l'horizon choisi
    prev = tableau_previsions(res, n).round(2)
    # Feuille 2 : métriques des 5 modèles, avec indication du modèle retenu
    comp = res["metriques"].copy()
    comp["Modèle retenu"] = np.where(comp["code"] == res["gagnant"], "Oui", "Non")
    comp = comp.drop(columns="code").rename(columns={
        "modele": "Modèle",
        "erreur_absolue_moyenne": "Erreur absolue moyenne (francs CFA)",
        "racine_erreur_quadratique": "Racine de l'erreur quadratique moyenne (francs CFA)",
        "erreur_pct_moyenne": "Erreur moyenne en pourcentage (%)",
    }).round(2)

    # Écriture en mémoire, puis ajustement de la largeur des colonnes
    tampon = BytesIO()
    with pd.ExcelWriter(tampon, engine="openpyxl") as ecrivain:
        prev.to_excel(ecrivain, sheet_name="Prévisions mensuelles", index=False)
        comp.to_excel(ecrivain, sheet_name="Comparaison des modèles", index=False)
        for feuille in ecrivain.sheets.values():
            for colonne in feuille.columns:
                largeur = max(len(str(c.value)) if c.value is not None else 0 for c in colonne)
                feuille.column_dimensions[colonne[0].column_letter].width = min(largeur + 3, 60)
    return tampon.getvalue()


def graphique_historique(res, n):
    """Courbe de gauche : historique + test + projection du meilleur modèle."""
    serie = res["serie"]
    prev = res["prevision"].head(n)
    dates_test = pd.to_datetime(res["dates_test"])
    nom = NOMS_MODELES[res["gagnant"]]

    fig, ax = plt.subplots(figsize=(7.2, 4.6))

    # 1. Historique complet
    ax.plot(serie["date_mois"], serie["ca_mensuel"], marker="o", ms=4, lw=2,
            color="#1F5FBF", label="Chiffre d'affaires réel")

    # 2. Zone et courbe de la période de test
    ax.axvspan(dates_test[0] - pd.Timedelta(days=15), dates_test[-1] + pd.Timedelta(days=15),
               color="#318CE7", alpha=0.10, label=f"Période de test ({MOIS_TEST} mois)")
    ax.plot(dates_test, res["pred_test"], marker="s", ms=4, ls="--", lw=2,
            color="#F28C28", label=f"Prévision sur le test ({nom})")

    # 3. Projection, reliée au dernier point réel pour la continuité visuelle
    xs = [serie["date_mois"].iloc[-1]] + list(prev["date_mois"])
    ys = [serie["ca_mensuel"].iloc[-1]] + list(prev["ca_prevu"])
    ax.plot(xs, ys, ls="--", lw=2, color="#2E9E5B", label=f"Projection ({n} mois)")
    ax.scatter(prev["date_mois"], prev["ca_prevu"], marker="D", s=36,
               facecolor="white", edgecolor="#2E9E5B", linewidth=1.8, zorder=3)
    ax.axvspan(prev["date_mois"].iloc[0] - pd.Timedelta(days=15),
               prev["date_mois"].iloc[-1] + pd.Timedelta(days=15),
               color="#2E9E5B", alpha=0.10)

    # 4. Mise en forme des axes (dates lisibles, millions sur l'axe vertical)
    ax.xaxis.set_major_locator(mdates.MonthLocator(interval=max(1, (len(serie) + n) // 12)))
    ax.xaxis.set_major_formatter(mdates.DateFormatter("%Y-%m"))
    plt.setp(ax.get_xticklabels(), rotation=45, ha="right", fontsize=8)
    ax.yaxis.set_major_formatter(FuncFormatter(lambda v, p: f"{v / 1e6:.0f} M"))
    ax.tick_params(axis="y", labelsize=8)
    ax.set_ylabel("Chiffre d'affaires net (francs CFA)", fontsize=9)
    ax.set_ylim(bottom=0)
    ax.grid(True, linestyle=":", alpha=0.6)
    for cote in ("top", "right"):
        ax.spines[cote].set_visible(False)
    ax.legend(loc="upper center", bbox_to_anchor=(0.5, -0.2), ncol=2, frameon=False, fontsize=8)
    fig.tight_layout()
    return fig


def graphique_comparaison(res):
    """Courbe de droite : histogramme groupé des 5 modèles sur les 3 métriques."""
    m = res["metriques"]
    groupes = [
        "Erreur moyenne\nen pourcentage (%)",
        "Erreur absolue moyenne\n(millions de francs CFA)",
        "Racine de l'erreur\nquadratique moyenne\n(millions de francs CFA)",
    ]
    largeur = 0.8 / len(m)       # largeur d'une barre
    x = np.arange(len(groupes))  # position des 3 groupes

    fig, ax = plt.subplots(figsize=(7.2, 4.6))
    # Une série de barres par modèle, avec la valeur écrite au-dessus de chaque barre
    for i, ligne in enumerate(m.itertuples()):
        valeurs = [
            ligne.erreur_pct_moyenne,
            ligne.erreur_absolue_moyenne / 1e6,
            ligne.racine_erreur_quadratique / 1e6,
        ]
        etiquette = ligne.modele + (" ★ (retenu)" if ligne.code == res["gagnant"] else "")
        barres = ax.bar(x - 0.4 + largeur * (i + 0.5), valeurs, largeur,
                        color=COULEURS_MODELES[ligne.code], label=etiquette)
        ax.bar_label(barres, labels=[fmt_decimal(v) for v in valeurs], fontsize=6.5, padding=2)

    # Mise en forme
    ax.set_xticks(x)
    ax.set_xticklabels(groupes, fontsize=8)
    ax.tick_params(axis="y", labelsize=8)
    ax.grid(True, axis="y", linestyle=":", alpha=0.6)
    ax.set_axisbelow(True)
    for cote in ("top", "right"):
        ax.spines[cote].set_visible(False)
    ax.legend(loc="upper center", bbox_to_anchor=(0.5, -0.22), ncol=3, frameon=False, fontsize=8)
    fig.tight_layout()
    return fig


